import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.next();
        int n = Integer.parseInt(line);
        Integer boxed = n;
        System.out.println("项链接回来是 " + n + " 条喵");
        System.out.println("装进口袋再拆出来：" + boxed);
        System.out.println("算式里先拆箱，加 {k} 得：" + (boxed + {k}));
        System.out.println("这张图纸最多装到 " + Integer.MAX_VALUE);
    }
}
